  }

  initialize(buf0);

  // これでいいですね。updateですね。めんどくさい。

  const vsUpdate =
`#version 300 es
in vec2 aPosition;
in vec2 aVelocity;
out vec2 vPosition;
out vec2 vVelocity;
uniform float uTime;
uniform float uSeed;
const float TAU = 6.28318;
const float PI = 3.14159;
const vec2 deltaX = vec2(0.000001, 0.0);
const vec2 deltaY = vec2(0.0, 0.000001);
${_SimplexNoise}
${distFunction2D}
${distFunctionForObstacles}
// 反射処理
bool applyReflect(in vec2 p, inout vec2 v){
  if(dist(p + v) < 0.0){
    vec2 n = normalize(vec2(dist(p + deltaX) - dist(p), dist(p + deltaY) - dist(p)));
    v = reflect(v, n) * 0.9;
    return true;
  }
  return false;
}
void main(){
  int i = gl_VertexID;
  int ix = i % ${SIZE};
  int iy = i / ${SIZE};
  vec2 fp = (vec2(float(ix), float(iy)) + 0.5) / ${SIZE}.0;
  vec2 p = aPosition;
  vec2 v = aVelocity;
  // 更新処理
  v.y -= 0.002;
  if(length(v) > 0.025){ v *= 0.9; }
  // 反射
  applyReflect(p, v);
  // 位置更新
  p += v;
  // 左右をつなげる
  if(p.x < -1.0){ p.x += 2.0; }
  if(p.x > 1.0){ p.x -= 2.0; }
  // 初期化
