    p.x = fract(2.0 + 2.0 * snoise3(vec3(fp.x, fp.y, uTime + uSeed))) * 2.0 - 1.0;
    p.y += 2.0;
    v.x = 0.01 * snoise3(vec3(uTime - uSeed, fp.x, fp.y));
    v.y = 0.0;
  }
  vPosition = p;
  vVelocity = v;
}
