    ctx.lineCap = "round";
    ctx.strokeStyle = 'teal';
    const halfAngle = Math.atan2(0.6, -0.8);
    const radius = O_SIZE * 0.3 / 4;
    // 外側の円弧
    for (let i=0; i<6; i+=1) {
      const angle = TAU*i/6;
      const angleOffset = time * TAU/8;
      const x = (0.75 * Math.cos(angle) + 1) * 0.5 * O_SIZE;
      const y = (-0.75 * Math.sin(angle) + 1) * 0.5 * O_SIZE;
      ctx.beginPath();
      ctx.arc(x, y, radius, angle + angleOffset - halfAngle, angle + angleOffset + halfAngle);
      ctx.stroke();
    }
    // 内側の円弧
    for (let i=0.5; i<3.5; i+=1) {
      const angle = TAU*i/3;
      const angleOffset = -time * TAU/8;
      const x = (0.3 * Math.cos(angle) + 1) * 0.5 * O_SIZE;
      const y = (-0.3 * Math.sin(angle) + 1) * 0.5 * O_SIZE;
      ctx.beginPath();
      ctx.arc(x, y, radius, angle + angleOffset - halfAngle, angle + angleOffset + halfAngle);
      ctx.stroke();
    }
    // 三角形
    const T_SIZE = O_SIZE*0.1/2;
    ctx.fillStyle = "green";

    const tf = ctx.getTransform();
    ctx.translate(O_SIZE*0.5, O_SIZE*0.5 + 0.85 * O_SIZE*0.5);
    ctx.rotate(time*TAU/6);
    ctx.beginPath();
    ctx.moveTo(T_SIZE*0.5, -T_SIZE*0.5*Math.sqrt(3));
    ctx.lineTo(T_SIZE*0.5, T_SIZE*0.5*Math.sqrt(3));
    ctx.lineTo(-T_SIZE, 0);
    ctx.closePath();
    ctx.fill();
    ctx.setTransform(tf);

    ctx.translate(O_SIZE*0.5, O_SIZE*0.5 - 0.85 * O_SIZE*0.5);
    ctx.rotate(-time*TAU/6);
    ctx.beginPath();
    ctx.moveTo(T_SIZE*0.5, -T_SIZE*0.5*Math.sqrt(3));
    ctx.lineTo(T_SIZE*0.5, T_SIZE*0.5*Math.sqrt(3));
    ctx.lineTo(-T_SIZE, 0);
    ctx.closePath();
    ctx.fill();
    ctx.setTransform(tf);

    // 更新
    gl.activeTexture(gl.TEXTURE0);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, O_SIZE, O_SIZE, 0, gl.RGBA, gl.UNSIGNED_BYTE, offscreen);
  }

  // テクスチャ描画用
  const vsTexture =
`#version 300 es
const vec2[4] pos = vec2[](
  vec2(-1.0,-1.0), vec2(1.0,-1.0), vec2(-1.0,1.0), vec2(1.0,1.0)
);
out vec2 vUv;
void main(){
  vec2 p = pos[gl_VertexID];
  vUv = 0.5 + p*0.5;
  vUv.y = 1.0 - vUv.y;
  gl_Position = vec4(p, 0.0, 1.0);
}
`;

  const fsTexture =
`#version 300 es
precision highp float;
in vec2 vUv;
out vec4 fragColor;
uniform sampler2D uTex;
void main(){
  fragColor = texture(uTex, vUv);
}
`;
  const pgTexture = createShaderProgram(gl, {vs:vsTexture, fs:fsTexture});

  const update = () => {
    // これ使って描画サイドもいじるんだとか。
    const currentTime = window.performance.now()/1000;
    updateOffscreen(currentTime);

    gl.useProgram(pgUpdate);
    uniformX(gl, pgUpdate, "1f", "uSeed", Math.random());
    uniformX(gl, pgUpdate, "1f", "uTime", currentTime);

    gl.bindVertexArray(vaos[bufIndex]);
    gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, tfos[bufIndex]);

    gl.beginTransformFeedback(gl.POINTS);
    gl.enable(gl.RASTERIZER_DISCARD);
    gl.drawArrays(gl.POINTS, 0, SIZE*SIZE);
    gl.disable(gl.RASTERIZER_DISCARD);
    gl.endTransformFeedback();

    gl.bindVertexArray(null);
    gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);

    bufIndex = 1-bufIndex;
  }

  // 描画？

  const vsDraw =
`#version 300 es
in vec2 aPosition;
uniform float uPointSize;
void main(){
  gl_Position = vec4(aPosition, 0.0, 1.0);
  gl_PointSize = uPointSize;
}
`;

  const fsDraw =
`#version 300 es
precision highp float;
out vec4 fragColor;
void main(){
  fragColor = vec4(0.5, 0.7, 0.9, 0.5);
}
`;

  const pgDraw = createShaderProgram(gl, {vs:vsDraw, fs:fsDraw});

  const _draw = () => {
    gl.clearColor(0,0,0,1);
    gl.clear(gl.COLOR_BUFFER_BIT);

    gl.enable(gl.BLEND);
    gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);

    gl.useProgram(pgDraw);
    uniformX(gl, pgDraw, "1f", "uPointSize", DPR);
    gl.bindVertexArray(vaosDraw[bufIndex]);
    gl.drawArrays(gl.POINTS, 0, SIZE*SIZE);
    gl.bindVertexArray(null);

    gl.useProgram(pgTexture);
    uniformX(gl, pgTexture, "1i", "uTex", 0);

    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

    gl.disable(gl.BLEND);
    gl.flush();
  }

  draw = () => {
    update();
    _draw();
  }

}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            try {
                if (typeof this.createGraphics === 'function') {
                    return this.createGraphics(10, 10);
                } else if (typeof createGraphics === 'function') {
                    return createGraphics(10, 10);
                }
            } catch(e) {}
            try {
                if (typeof this.createImage === 'function') {
                    return this.createImage(1, 1);
                }
            } catch(e) {}
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return {
                width: 1,
                height: 1,
                pixels: [0, 0, 0, 0],
                loadPixels: function() {},
                updatePixels: function() {},
                get: function() { return [0, 0, 0, 255]; },
                vertices: []
            };
        }
    };
}

